        let r = a & b;

        // Check the required bitwise AND properties at this index
        assert(r == b & a);
        assert(a & 0u8 == 0u8);
        assert(0u8 & b == 0u8);
        assert(a & a == a);
        assert(b & b == b);
        assert(r <= a);
